<script setup>
import {computed,ref,onMounted} from 'vue'
import Icon from '../Icon.vue'
import {request} from './client'
const data=ref(null),error=ref(''),busy=ref(false)
const available=computed(()=>['Active','Trial'].includes(data.value?.state))
const price=computed(()=>data.value?.monthly_lkr==null?null:new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR',minimumFractionDigits:2}).format(data.value.monthly_lkr))
async function load(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await request('classroom_handover','institute_plan',{},'GET')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
 <section class="institute-plan-page" :aria-busy="busy">
  <header class="plan-heading"><div><h1>Institute plan</h1><p>Your institute manages its subscription.</p></div><button class="plan-refresh" :disabled="busy" @click="load"><Icon name="RotateCcw" :size="17"/>{{busy?'Checking…':'Refresh status'}}</button></header>
  <p v-if="error" class="plan-error" role="alert">{{error}} <button @click="load" :disabled="busy">Try again</button></p>
  <section v-if="data" class="plan-summary" aria-labelledby="institute-plan-name">
   <header class="plan-identity"><span class="plan-emblem"><Icon name="Building2" :size="26"/></span><div><h2 id="institute-plan-name">{{data.institute}}</h2><p>Institute workspace</p></div><span class="plan-status" :class="{'is-available':available}"><Icon :name="available?'CircleCheck':'Clock3'" :size="15"/>{{data.state}}</span></header>
   <div class="plan-content">
    <div class="plan-details"><span class="plan-label">Subscription plan</span><h3>{{data.plan?'SISU '+data.plan:'No plan selected'}}</h3><p v-if="data.description" class="plan-description">{{data.description}}</p><p v-if="price" class="plan-price"><strong>{{price}}</strong><span>/ month base fee</span></p><p v-else class="plan-description">Plan details are not available yet.</p><p class="plan-managed"><Icon name="ShieldCheck" :size="18"/><span>Billing and plan changes are managed by your institute administrator.</span></p></div>
    <div class="plan-features"><h3>Included in this plan</h3><ul v-if="data.card_features?.length"><li v-for="(feature,index) in data.card_features" :key="index"><Icon name="Check" :size="18"/><span>{{feature}}</span></li></ul><p v-else>Included features will appear once your institute selects a plan.</p><p v-if="!available" class="plan-availability"><Icon name="LockKeyhole" :size="17"/><span>These features become available when your institute’s subscription is active.</span></p></div>
   </div>
   <footer class="plan-help"><Icon name="CircleHelp" :size="20"/><div><strong>{{available?'Questions about your access?':'Need access to this workspace?'}}</strong><p>Contact your institute administrator about plan access or changes. You can switch to Personal using the workspace menu beside your profile.</p></div></footer>
  </section>
  <p v-else-if="!error" class="plan-loading" role="status">Loading institute plan…</p>
 </section>
</template>
