.plan-help{display:flex;align-items:flex-start;gap:12px;padding:22px 30px;background:#f8f5fc;border-top:1px solid var(--plan-line)}.plan-help>svg{flex-shrink:0;color:var(--plan-purple);margin-top:2px}.plan-help strong{font-size:14px}.plan-help p{font-size:13px;line-height:1.7;color:var(--plan-muted);margin:5px 0 0;max-width:85ch}.plan-error{padding:16px;background:#fff1f2;color:#963748;border-radius:10px;font-size:14px;line-height:1.7}.plan-error button{background:none;border:0;color:inherit;text-decoration:underline;text-underline-offset:3px;font:inherit;cursor:pointer;min-height:44px}.plan-loading{color:var(--plan-muted);padding:30px 0}.institute-plan-page ::selection{background:#eadcf6;color:#38224d}
