@media(max-width:420px){.plan-content,.plan-identity,.plan-help{padding:20px}.plan-identity h2{font-size:18px}.plan-emblem{width:44px;height:44px}.plan-identity>div{flex:1}.plan-status{margin-left:56px}.plan-refresh{width:100%}}
